#!/usr/bin/env python3
"""Install repo git hooks into .git/hooks (no git config changes)."""

from __future__ import annotations

import os
import stat
import sys
from pathlib import Path


PRE_COMMIT_BODY = """#!/bin/sh
# Auto-generated by scripts/install_git_hooks.py — do not edit.
set -e
ROOT="$(git rev-parse --show-toplevel)"
cd "$ROOT"
# Use the explicitly selected campaign environment for the gate as well. On
# Windows, the Store python3 alias can rewrite PYTHONUSERBASE for its children.
if [ -n "${ENTMOOT_CAMPAIGN_PYTHON:-}" ]; then
  PY="$ENTMOOT_CAMPAIGN_PYTHON"
elif command -v python >/dev/null 2>&1 && python -c 'import sys; sys.exit(sys.version_info < (3, 11))' >/dev/null 2>&1; then
  PY=python
elif command -v python3 >/dev/null 2>&1; then
  PY=python3
else
  echo "pre-commit: python3/python not found on PATH" >&2
  exit 1
fi
# Always-on policy + ownership validate; structural noop may skip clippy/tests.
"$PY" "$ROOT/scripts/pre_commit_check.py"
"""


def _write_hook(path: Path, body: str) -> None:
    path.write_text(body, encoding="utf-8", newline="\n")
    mode = path.stat().st_mode
    path.chmod(mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
    if os.name == "nt":
        try:
            os.chmod(path, stat.S_IRWXU | stat.S_IRGRP | stat.S_IROTH)
        except OSError:
            pass


def main() -> int:
    root = Path(__file__).resolve().parents[1]
    hooks_dir = root / ".git" / "hooks"
    if not hooks_dir.is_dir():
        print(f"Not a git checkout (missing {hooks_dir})", file=sys.stderr)
        return 1

    pre_commit = hooks_dir / "pre-commit"
    post_commit = hooks_dir / "post-commit"
    _write_hook(pre_commit, PRE_COMMIT_BODY)
    # MCP dogfood refresh is parked; remove a prior post-commit if present.
    if post_commit.exists():
        post_commit.unlink()
        print(f"Removed parked post-commit hook -> {post_commit}")

    print(f"Installed pre-commit hook -> {pre_commit}")
    print(
        "pre-commit runs: banned-pattern / crate / markdown / test-ownership gates, "
        "fmt and Python unit tests. Path ownership (scripts/test_ownership.json) selects "
        "Clippy, Cargo tests and binary-backed campaigns; configuration-only evaluation "
        "changes run Python harness tests without rebuilding Entmoot. "
        "CI stays authoritative. Optional .pre-commit-config.yaml delegates to the same script."
    )
    print(
        "post-commit: not installed (MCP local-index refresh is parked; see "
        "archive/entmoot-mcp/PARKED.md)"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
